// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;

    function setUp() public { c = new airdrop(); }

    // fuzzed params: an address that will be the caller (actor) and a uint256 length for the _tos array
    // We cannot fuzz an address to act as a callee because EOAs always succeed on low-level call.
    // So we deploy a RecordingCallee that implements transferFrom(address,address,uint256) and records calls.
    // We fuzz the array length (n) and n distinct recipient addresses derived from a seed by vm.addr.
    function testFuzz_property(uint256 seed, uint256 n) public {
        // keep n to a reasonable bound so the test runs quickly but allow >0
        n = bound(n, 0, 10);

        // Adversarial/Observing callee that always returns true (succeeds) and records each call
        RecordingCallee callee = new RecordingCallee();

        // Build _tos array of length n. Use derived addresses so fuzz controls them via seed.
        address[] memory tos = new address[](n);
        for (uint256 i = 0; i < n; i++) {
            // derive an address from seed and index so fuzzer explores space
            tos[i] = vm.addr(uint256(keccak256(abi.encodePacked(seed, i))));
        }

        bool ok;
        // Call transfer and observe whether it completes or reverts.
        try c.transfer(address(this), address(callee), tos, 1) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE: For every admissible input (any seed and any n >= 1), when the callee's
        // transferFrom function succeeds for each call, the reference implementation completes
        // and thus ok == true. The mutant that loops with i<=_tos.length can index out of bounds
        // when n>0 and will sometimes revert, making ok == false for some inputs.
        // We assert the universal property for the reference: if n > 0 then call must succeed.

        if (n > 0) {
            assertTrue(ok);
        } else {
            // if n == 0 the contract requires _tos.length > 0, so it reverts; both ref and mutant revert
            // ensure we observed a revert in that case
            assertTrue(!ok);
        }

        // Additionally, verify that when n>0 the callee recorded exactly n calls (sanity for reference)
        // (This reads the helper's public getter which is allowed.)
        if (n > 0) {
            assertTrue(callee.callCount() == n);
        }
    }
}

// Recording callee: matches the selector transferFrom(address,address,uint256)
contract RecordingCallee {
    uint256 public callCount;
    address[] public lastFroms;
    address[] public lastTos;
    uint256[] public lastVals;

    // must match selector used by C: transferFrom(address,address,uint256)
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        callCount++;
        lastFroms.push(from);
        lastTos.push(to);
        lastVals.push(v);
        return true; // succeed to exercise the normal path
    }
}
